"""Copy every disbursement from the Meridian Disbursements API (v2) into disbursements.jsonl."""
import argparse
import json
import urllib.request


def fetch_disbursements(base_url):
    """Export all disbursements via the v2 paged endpoint, deduplicating on id."""
    disbursements = {}
    cursor = None
    while True:
        url = f"{base_url}/v2/disbursements"
        if cursor is not None:
            url += f"?cursor={urllib.parse.quote(cursor)}"
        with urllib.request.urlopen(url, timeout=30) as resp:
            page = json.load(resp)
        for d in page["disbursements"]:
            disbursements[d["id"]] = d
        if page["drained"]:
            break
        cursor = page["cursor"]
    return list(disbursements.values())


def verify_sync(base_url, disbursements):
    body = json.dumps({"disbursements": disbursements}).encode()
    req = urllib.request.Request(
        f"{base_url}/v2/verify",
        data=body,
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(req, timeout=30) as resp:
        return json.load(resp)


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base-url", required=True)
    ap.add_argument("--out", default="disbursements.jsonl")
    ap.add_argument("--verify", action="store_true", help="verify the sync via POST /v2/verify")
    args = ap.parse_args()
    base_url = args.base_url.rstrip("/")
    disbursements = fetch_disbursements(base_url)
    with open(args.out, "w") as f:
        for d in disbursements:
            f.write(json.dumps(d) + "\n")
    print(f"synced {len(disbursements)} disbursements")
    if args.verify:
        print(json.dumps(verify_sync(base_url, disbursements)))


if __name__ == "__main__":
    main()

